// Builds the EventSource Client options for /v1/alerts/stream and resumes
// from the last alert rev seen (persisted in flow context; configure a
// persistent context store in settings.js so it survives restarts).
const base = env.get('FORESIGNAL_URL');          // e.g. http://foresignal.local:8080
const token = env.get('FORESIGNAL_TOKEN');       // a read token
if (!base || !token) {
    node.error('Set FORESIGNAL_URL and FORESIGNAL_TOKEN in the Node-RED environment');
    return null;
}
const options = {
    url: base + '/v1/alerts/stream?minSeverity=warning',
    headers: { Authorization: 'Bearer ' + token }
};
const last = flow.get('foresignal_alert_rev');
if (last) {
    options.initialLastEventId = String(last);
}
msg.payload = options;
return msg;

// One server-sent event from /v1/alerts/stream: {event, id, data}.
// alert, alert.updated and alert.resolved carry id = the alert rev; heartbeat
// and other control events have no id.
const ev = msg.payload || {};
if (ev.id) {
    flow.set('foresignal_alert_rev', ev.id);
}
if (!['alert', 'alert.updated', 'alert.resolved'].includes(ev.event)) {
    return null;
}
let data;
try {
    data = JSON.parse(ev.data);
} catch (e) {
    node.warn('Unparseable alert event: ' + e.message);
    return null;
}
// Upsert by alert id: a resume replays alerts in their current state.
msg.topic = ev.event;
msg.payload = data;
return msg;

// Verifies X-Foresignal-Signature over the raw body (the http in node has
// "Do not parse request body" on, so msg.payload is a Buffer).
// sha256=<hex HMAC-SHA256(secret, "<X-Foresignal-Timestamp>.<body>")>
const secret = env.get('FORESIGNAL_WEBHOOK_SECRET');
const ts = msg.req.headers['x-foresignal-timestamp'];
const sig = msg.req.headers['x-foresignal-signature'] || '';
const body = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(String(msg.payload || ''), 'utf8');
const age = Math.abs(Date.now() / 1000 - Number(ts));
let ok = Boolean(secret) && Boolean(ts) && Number.isFinite(age) && age <= 300;
if (ok) {
    const mac = crypto.createHmac('sha256', secret);
    mac.update(ts + '.');
    mac.update(body);
    const expected = Buffer.from('sha256=' + mac.digest('hex'));
    const given = Buffer.from(sig);
    ok = expected.length === given.length && crypto.timingSafeEqual(expected, given);
}
// Output 1: the verified notification. Output 2: the HTTP reply (always).
const reply = { req: msg.req, res: msg.res, statusCode: ok ? 204 : 401, payload: '' };
if (!ok) {
    return [null, reply];
}
const out = { payload: JSON.parse(body.toString('utf8')) };
out.topic = out.payload.subtype;   // alert.fired, alert.acknowledged, ...
return [out, reply];

// Builds one record for POST /v1/ingest/{sourceId} (native format).
// The source and its ingest key come from the environment; the key can only
// write to that source.
const base = env.get('FORESIGNAL_URL');
const sourceId = env.get('FORESIGNAL_INGEST_SOURCE');  // e.g. custom-nodered
const key = env.get('FORESIGNAL_INGEST_KEY');           // eik_...
msg.method = 'POST';
msg.url = base + '/v1/ingest/' + encodeURIComponent(sourceId);
msg.headers = { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' };
msg.payload = {
    records: [{
        externalId: 'nodered-demo',
        kind: 'sensor-reading',
        observedAt: new Date().toISOString(),
        geometry: { type: 'Point', coordinates: [-95.99, 36.15] },
        payload: { value: Math.round(Math.random() * 1000) / 10, unit: 'C' }
    }]
};
return msg;
